const before=editor.getText();
const s=ShellScript.create("#!/bin/sh\nprintf \"%s\" \"$1\"; printf \"warning café\\n\" >&2; exit 7");
if(s.execute(['literal café 🐼'])!==false)throw Error('Nonzero status was not false');
if(s.standardOutput!=='literal café 🐼'||s.standardError!=="warning café\n")throw Error('Incorrect native streams: '+JSON.stringify([s.standardOutput,s.standardError]));
if(editor.getText()!==before)throw Error('Editor changed');
app.displaySuccessMessage('Nonzero false; Unicode stdout/stderr passed');

const before=editor.getText();
const s=ShellScript.create('#!/draftly-qa/missing-interpreter\n');
if(s.execute([])!==false)throw Error('Launch failure was not false');
if(editor.getText()!==before)throw Error('Editor changed');
context.addSuccessParameter('launchHandled','false');
app.displaySuccessMessage('Launch failure returned false; editor preserved');
